/**
 * One key, the kind's name, holding its fields. A kind this build does not know is kept whole and
 * written back as it was read (TranscriptEntry+Coding.swift).
 */
export type TranscriptEntryKind =
  | { userMessage: { _0: string; blocks?: ContentBlock[]; from?: PromptOrigin } }
  | { agentMessage: { messageID?: string; text: string; blocks?: ContentBlock[] } }
  | { agentThought: { messageID?: string; text: string } }
  | { toolCall: { _0: ToolCall } }
  | { toolCallUpdate: { _0: ToolCall } }
  | { planUpdated: { _0: Plan } }
  | { usageRecorded: { _0: TurnUsage } }
  | { servedRequest: { _0: ServedRequest } }
  | { elicitationAsked: { _0: ElicitationRequest } }
  | { elicitationAnswered: { id: UUID; summary: string; answers?: ElicitationAnswer[] } }
  | { compaction: { status: string; summary: ContentBlock[]; id?: string; error?: string } }
  | { notice: { _0: SessionNotice } }
  | { permissionAsked: { _0: PermissionRequest } }
  | { permissionAnswered: { optionID: string; optionName?: string } }
  | { optionChanged: { id: string; value: JSONValue } }
  | { stateChanged: { _0: AgentState; reason?: EndedReason } }
  | { background: { _0: BackgroundItem } }
  | { workReported: { _0: WorkReport } }
  | { runtimeNote: { _0: string } }
  | { poolSwitch: { _0: SwitchRecord } }
  | { sandboxFailure: { _0: SandboxFailureRecord } }
  | { handoff: { markdown: string; characters: number } }
  | { settingsChanged: { _0: SwitchRecord } }
  | { appView: { _0: AppViewCall } }
  | { fileShown: { _0: ShownFile } };

